"use client";

import { type VariantProps, cva } from "class-variance-authority";
import * as React from "react";
import { cn } from "../../lib/utils.js";

/** A file-shaped attachment metadata object accepted by `<Attachment>`. */
export interface AttachmentFile {
	/** Display name. */
	name: string;
	/** Bytes. Used to render a human-readable size. */
	size: number;
	/** MIME type. Drives the auto-detected `variant`. */
	type: string;
	/**
	 * Optional preview URL for images. When `type` starts with `image/`
	 * AND `preview` is set, the attachment renders a thumbnail; otherwise
	 * it falls back to a typed file icon + name + size.
	 */
	preview?: string;
}

const attachmentVariants = cva(
	[
		"group/attachment relative inline-flex items-center gap-[var(--gap-sm,0.5rem)] rounded-md border border-border bg-card",
		"transition-all duration-[var(--duration-normal,200ms)] ease-out",
	].join(" "),
	{
		variants: {
			variant: {
				file: "px-[var(--space-3,0.75rem)] py-[var(--space-2,0.5rem)] max-w-xs",
				image: "p-0 overflow-hidden",
			},
		},
		defaultVariants: { variant: "file" },
	},
);

export interface AttachmentProps
	extends Omit<React.HTMLAttributes<HTMLDivElement>, "onProgress">,
		VariantProps<typeof attachmentVariants> {
	/** Forwarded ref onto the root element. */
	ref?: React.Ref<HTMLDivElement>;
	/** Native `File` OR a metadata object. */
	file: File | AttachmentFile;
	/** Click handler for the remove button. When provided, a × button overlays the attachment. */
	onRemove?: () => void;
	/**
	 * Upload progress in `[0, 1)`. Values `>= 1` (or `undefined`) hide the
	 * progressbar — pass `undefined` once the upload completes. Internally
	 * scaled to `aria-valuenow` on a 0–100 progressbar so AT engines
	 * announce "42 percent" rather than "0.42 of 1."
	 */
	progress?: number;
}

/**
 * Format a byte count as a human-readable size (`"24.3 KB"`, `"1.2 MB"`).
 *
 * @param bytes - Raw byte count.
 * @returns A short human-readable string.
 */
function formatSize(bytes: number): string {
	if (bytes < 1024) return `${bytes} B`;
	if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
	if (bytes < 1024 * 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
	return `${(bytes / (1024 * 1024 * 1024)).toFixed(1)} GB`;
}

/**
 * Decide whether to render the image variant (thumbnail) vs the file
 * variant (icon + name + size). Images need both an image MIME type AND
 * a `preview` URL — without preview we can't actually show the image, so
 * we fall back to the file variant.
 *
 * @param file - The attachment input.
 * @returns `"image"` when both conditions hold, else `"file"`.
 */
function detectVariant(file: File | AttachmentFile): "image" | "file" {
	const preview = "preview" in file ? file.preview : undefined;
	const isImage = file.type.startsWith("image/");
	return isImage && preview ? "image" : "file";
}

/**
 * Resolve the preview URL for an attachment input. Native `File`s don't
 * carry a preview; consumers create one via `URL.createObjectURL(file)`
 * before handing the file in.
 *
 * @param file - The attachment input.
 * @returns The preview URL, or undefined.
 */
function resolvePreview(file: File | AttachmentFile): string | undefined {
	return "preview" in file ? file.preview : undefined;
}

/**
 * A file / image attachment thumbnail with an optional remove affordance
 * and optional upload-progress overlay. Composes with the existing
 * `Composer` AI primitive (drop into Composer's children slot to render
 * as part of the message draft).
 *
 * Auto-detects the visual variant: image MIME + `preview` URL → image
 * thumbnail; everything else → typed file icon with name + size.
 *
 * Distinct from {@link Dropzone} (the upload-input affordance) and
 * static {@link Card} previews (no remove/progress UI).
 *
 * @example
 * ```tsx
 * <Attachment
 *   file={{ name: "screenshot.png", size: 124000, type: "image/png", preview: objectUrl }}
 *   onRemove={() => removeFromDraft("screenshot.png")}
 * />
 * ```
 */
function Attachment({
	className,
	variant,
	file,
	onRemove,
	progress,
	ref,
	...props
}: AttachmentProps) {
	const preview = resolvePreview(file);
	// M3: when caller forces variant="image" but no preview is available,
	// fall back to "file" so the wrapper padding matches the rendered
	// content (file icon + name + size needs px/py; image uses zero-pad).
	const detected = detectVariant(file);
	const resolvedVariant: "image" | "file" =
		variant === "image" && !preview ? "file" : (variant ?? detected);
	const showProgress = typeof progress === "number" && progress >= 0 && progress < 1;
	// M5: scale to 0–100 so AT announces "42 percent" not "0.42 of 1."
	const progressPercent = showProgress ? Math.round(progress * 100) : 0;

	return (
		<div
			ref={ref}
			className={cn(attachmentVariants({ variant: resolvedVariant }), className)}
			{...props}
		>
			{resolvedVariant === "image" && preview ? (
				// Intentional plain <img> (not next/image) — Attachment is
				// framework-agnostic. Consumers can swap in next/image at the
				// callsite when they want optimization.
				<img
					src={preview}
					alt={file.name}
					className="block h-20 w-20 object-cover"
				/>
			) : (
				<>
					<FileIcon className="h-5 w-5 shrink-0 text-muted-foreground" />
					<div className="flex min-w-0 flex-col">
						<span className="truncate text-sm font-medium text-foreground">{file.name}</span>
						<span className="text-xs text-muted-foreground">{formatSize(file.size)}</span>
					</div>
				</>
			)}

			{showProgress ? (
				<div
					role="progressbar"
					aria-valuemin={0}
					aria-valuemax={100}
					aria-valuenow={progressPercent}
					aria-label={`Uploading ${file.name}`}
					className="absolute inset-x-0 bottom-0 h-1 overflow-hidden rounded-b-md bg-muted"
				>
					<div
						className="h-full bg-primary transition-[width] duration-[var(--duration-normal,200ms)] ease-out"
						style={{ width: `${progressPercent}%` }}
					/>
				</div>
			) : null}

			{onRemove ? (
				<button
					type="button"
					onClick={onRemove}
					aria-label={`Remove ${file.name}`}
					className={cn(
						"absolute -right-2 -top-2 inline-flex h-5 w-5 items-center justify-center rounded-full",
						"bg-card border border-border text-foreground shadow-sm",
						"transition-all duration-[var(--duration-normal,200ms)] ease-out",
						"hover:bg-accent hover:scale-110 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
						"active:scale-[0.98]",
					)}
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						fill="none"
						stroke="currentColor"
						strokeWidth="2.5"
						strokeLinecap="round"
						strokeLinejoin="round"
						className="size-3"
						aria-hidden="true"
					>
						<line x1="18" y1="6" x2="6" y2="18" />
						<line x1="6" y1="6" x2="18" y2="18" />
					</svg>
				</button>
			) : null}
		</div>
	);
}

/** Generic file icon (page-with-fold). */
function FileIcon(props: React.SVGAttributes<SVGElement>) {
	return (
		<svg
			xmlns="http://www.w3.org/2000/svg"
			viewBox="0 0 24 24"
			fill="none"
			stroke="currentColor"
			strokeWidth="2"
			strokeLinecap="round"
			strokeLinejoin="round"
			aria-hidden="true"
			{...props}
		>
			<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
			<polyline points="14 2 14 8 20 8" />
		</svg>
	);
}

export { Attachment, attachmentVariants };

/**
 * Color conversion utilities for the HSL-triplet token format used across
 * `@hex-core/tokens` themes (`H S% L%`, e.g. `"240 5.9% 10%"` — no `hsl()`
 * wrapper, no commas).
 *
 * The triplet is the round-trip-safe serialization for Hex Core: tokens flow
 * triplet → CSS `hsl(var(--token))` → rendered color, and the ColorPicker
 * component edits triplets directly. Hex/RGB conversions are display
 * adapters, not the source of truth.
 */

/** Parsed HSL components. `h` is degrees (0–360); `s` and `l` are percentages (0–100). */
export interface HslTriplet {
	h: number;
	s: number;
	l: number;
}

/** Parsed RGB components. Each channel is 0–255. */
export interface RgbColor {
	r: number;
	g: number;
	b: number;
}

/**
 * Parse an HSL triplet string into numeric components.
 *
 * Note: malformed input silently coerces to `{0,0,0}` (pure black) rather than
 * returning an error signal. Callers that need to distinguish "user typed
 * black" from "user typed garbage" should validate the input format first.
 * `hexToHslTriplet` returns `null` for malformed hex; this asymmetry is
 * intentional — triplets feed CSS variables where any non-color value would
 * already break rendering.
 *
 * @param triplet - String in the form `"<H> <S>% <L>%"` (e.g. `"240 5.9% 10%"`).
 * @returns Numeric components, or `{0,0,0}` if the input is malformed.
 */
export function parseHslTriplet(triplet: string): HslTriplet {
	const parts = triplet.trim().split(/\s+/);
	return {
		h: Number.parseFloat(parts[0]) || 0,
		s: Number.parseFloat(parts[1]) || 0,
		l: Number.parseFloat(parts[2]) || 0,
	};
}

/**
 * Format HSL components into an HSL triplet string (the canonical token format).
 * @param hsl - Numeric components.
 * @returns Triplet in the form `"<H> <S>% <L>%"`.
 */
export function formatHslTriplet({ h, s, l }: HslTriplet): string {
	// Tolerant integer check: rgbToHsl can produce values like 5.0000000001 due
	// to float arithmetic; format those as "5" rather than "5.0".
	const round = (n: number) =>
		Math.abs(n - Math.round(n)) < 1e-6 ? `${Math.round(n)}` : n.toFixed(1);
	return `${Math.round(h)} ${round(s)}% ${round(l)}%`;
}

/**
 * Convert HSL components to RGB.
 * @param h - Hue (0–360).
 * @param s - Saturation (0–100).
 * @param l - Lightness (0–100).
 * @returns RGB channels (0–255, rounded).
 */
export function hslToRgb(h: number, s: number, l: number): RgbColor {
	const sN = s / 100;
	const lN = l / 100;
	const k = (n: number) => (n + h / 30) % 12;
	const a = sN * Math.min(lN, 1 - lN);
	const f = (n: number) => lN - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
	return {
		r: Math.round(255 * f(0)),
		g: Math.round(255 * f(8)),
		b: Math.round(255 * f(4)),
	};
}

/**
 * Convert RGB components to HSL.
 * @param r - Red (0–255).
 * @param g - Green (0–255).
 * @param b - Blue (0–255).
 * @returns HSL components (h: 0–360, s: 0–100, l: 0–100).
 */
export function rgbToHsl(r: number, g: number, b: number): HslTriplet {
	const rN = r / 255;
	const gN = g / 255;
	const bN = b / 255;
	const max = Math.max(rN, gN, bN);
	const min = Math.min(rN, gN, bN);
	let h = 0;
	let s = 0;
	const l = (max + min) / 2;
	if (max !== min) {
		const d = max - min;
		s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
		if (max === rN) h = (gN - bN) / d + (gN < bN ? 6 : 0);
		else if (max === gN) h = (bN - rN) / d + 2;
		else h = (rN - gN) / d + 4;
		h /= 6;
	}
	return { h: h * 360, s: s * 100, l: l * 100 };
}

/**
 * Convert an HSL triplet to a 6-digit hex string.
 * @param triplet - HSL triplet (e.g. `"240 5.9% 10%"`).
 * @returns Lowercase hex string with leading `#` (e.g. `"#181a1f"`).
 */
export function hslTripletToHex(triplet: string): string {
	const { h, s, l } = parseHslTriplet(triplet);
	const { r, g, b } = hslToRgb(h, s, l);
	const toHex = (n: number) => n.toString(16).padStart(2, "0");
	return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

/**
 * Convert a hex string to an HSL triplet.
 * Accepts 3-digit (`#abc`) or 6-digit (`#aabbcc`) hex with optional `#`.
 * @param hex - Hex color string.
 * @returns HSL triplet, or `null` if the input is malformed.
 */
export function hexToHslTriplet(hex: string): string | null {
	const clean = hex.trim().replace(/^#/, "");
	let normalized: string;
	if (/^[0-9a-fA-F]{3}$/.test(clean)) {
		normalized = clean
			.split("")
			.map((c) => c + c)
			.join("");
	} else if (/^[0-9a-fA-F]{6}$/.test(clean)) {
		normalized = clean;
	} else {
		return null;
	}
	const r = Number.parseInt(normalized.slice(0, 2), 16);
	const g = Number.parseInt(normalized.slice(2, 4), 16);
	const b = Number.parseInt(normalized.slice(4, 6), 16);
	return formatHslTriplet(rgbToHsl(r, g, b));
}

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * Merge class names with Tailwind CSS conflict resolution.
 * @param inputs - Class values (strings, arrays, objects) to merge
 * @returns A single merged class string with Tailwind conflicts resolved
 */
export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

const SAFE_URL_SCHEMES = ["http:", "https:", "mailto:"] as const;

/**
 * Allowlist a URL for use as an `<a href>` against untrusted input.
 *
 * Returns the raw string when it's `http(s):` / `mailto:` / a relative
 * URL (no scheme); returns `undefined` otherwise. Defends against
 * `javascript:` / `data:` / `vbscript:` injection from streamed model
 * output or third-party JSON payloads that flow into citation chips.
 *
 * Inside a Markdown render path, `rehype-sanitize` already strips
 * `javascript:` from inline-link hrefs — but it does NOT introspect
 * JSON nested inside attribute values (e.g. `<sources data='[…]'/>`),
 * so the components that consume that data must guard themselves.
 *
 * @param raw - The candidate URL, or `undefined` when none was supplied.
 * @returns The URL when safe to render, otherwise `undefined`.
 */
export function safeUrl(raw: string | undefined): string | undefined {
	if (raw === undefined || raw === "") return undefined;
	// Relative URLs have no scheme — `new URL(relative)` throws without a base,
	// so a thrown URL means either malformed input OR a relative path. Treat
	// "throws + does not contain a colon" as a relative path (safe).
	let parsed: URL;
	try {
		parsed = new URL(raw);
	} catch {
		return raw.includes(":") ? undefined : raw;
	}
	return SAFE_URL_SCHEMES.some((scheme) => scheme === parsed.protocol) ? raw : undefined;
}

